ACT['a2c-chip'] = function(el){ ui('a2conf', {}).chip = el.getAttribute('data-v'); ui('a2conf', {}).id = null; rerender(); };
ACT['a2c-pick'] = function(el, ev){ if(ev.target.closest('input')) return; ui('a2conf', {}).id = el.getAttribute('data-id'); rerender(); };
CHANGE['a2c-sel'] = function(el){ ui('a2conf', {}).sel[el.getAttribute('data-id')] = el.checked; rerender(); };
ACT['a2c-bulk'] = function(){ var u = ui('a2conf', {}), ids = Object.keys(u.sel).filter(function(k){ return u.sel[k]; }), n = 0; ids.forEach(function(id){ if(A2C.confirm(ST.orders[id])) n++; }); u.sel = {}; saveState(); rerender(); toast(n + L(' confirmed', 'টা কনফার্ম হয়েছে') + (ids.length - n ? ' · ' + (ids.length - n) + L(' skipped', 'টা বাদ') : '')); };
ACT['a2c-call'] = function(el){ var o = a2Order(el.getAttribute('data-id')); A2C.call(o, el.getAttribute('data-v')); saveState(); rerender(); toast(L('Call logged', 'কল লেখা হয়েছে')); };
ACT['a2c-creq'] = function(el){ var o = a2Order(el.getAttribute('data-id')), ok = el.getAttribute('data-v') === 'ok'; if(ok){ a2Confirm({title:'Approve the cancel?', bn:'বাতিল মেনে নেবেন?', effects:[L('The order is cancelled with reason “Customer cancelled before confirming”', 'অর্ডার বাতিল হবে'), L('Held stock goes back; a cancel notice is sent once', 'স্টক ফেরত যাবে; একবার নোটিস যাবে')], reason:'optional', tone:'badf', ok:'Approve cancel', okBn:'বাতিল', fn:function(r){ A2C.cancel(o, 'CUSTOMER_BEFORE_CONFIRM', r || a2O(o).cancelReq.why); saveState(); rerender(); toast(L('Cancelled', 'বাতিল হয়েছে')); }}); }
  else { a2O(o).cancelReq = null; a2Ev(o, L('Cancel request refused — customer kept the order', 'বাতিলের অনুরোধ নেওয়া হয়নি'), 'info'); saveState(); rerender(); } };

