function a2RiskDecide(o, what){ var r = a2O(o).risk; r.decided = {by:a2Who(), what:what, at:Date.now()}; r.review = false; a2Ev(o, L('Risk review: ', 'ঝুঁকি যাচাই: ') + what, 'info'); }
