ACT['a2r-bulk'] = function(){ var u = ui('a2risk', {}), n = 0; a2Orders().forEach(function(o){ var r = a2O(o).risk; if(r && r.review && !r.decided && r.section === u.sec && a2Open(o)){ a2RiskDecide(o, L('Approved (section bulk)', 'অনুমোদিত (একসাথে)')); n++; } }); saveState(); rerender(); toast(n + L(' approved', 'টা অনুমোদিত')); };
ACT['a2r-hold'] = function(el){ var o = a2Order(el.getAttribute('data-id')); a2Confirm({title:'Hold this order', bn:'অর্ডার হোল্ড', reason:true, fn:function(r){ a2RiskDecide(o, L('Held: ', 'হোল্ড: ') + r); A2C.hold(o, r); saveState(); rerender(); }}); };
ACT['a2r-decline'] = function(el){ var o = a2Order(el.getAttribute('data-id'));
  a2Confirm({title:'Decline this order?', bn:'অর্ডার বাতিল করবেন?', effects:[L('Cancelled with reason “Declined after risk review”', '“ঝুঁকি যাচাইয়ে বাতিল” কারণসহ বাতিল'), L('The customer gets the decline notice (Messages → Order journey)', 'কাস্টমার নোটিস পাবে'), L('Never a block — that is a separate proposal', 'এটা ব্লক নয়')], reason:true, tone:'badf', ok:'Decline', okBn:'বাতিল', fn:function(r){ a2RiskDecide(o, L('Declined: ', 'বাতিল: ') + r); A2C.cancel(o, 'RISK_DECLINED', r); saveState(); rerender(); }}); };
ACT['a2r-merge'] = function(el){ var o = a2Order(el.getAttribute('data-id')), m = ST.orders[(a2O(o).risk.match || [])[0]];
  if(!m || !a2Open(m) || a2Booked(m)) return toast(L('The other order is already booked — send as a second parcel instead', 'অন্য অর্ডারটা বুক হয়ে গেছে'));
  a2Confirm({title:'Merge into one parcel?', bn:'এক পার্সেলে জোড়া দেবেন?', effects:[L('Items of ', '') + o.id + L(' move into ', ' এর পণ্য যাবে ') + m.id, L('One delivery charge is saved for the customer', 'কাস্টমারের একটা ডেলিভারি চার্জ বাঁচবে'), o.id + L(' is cancelled as “Duplicate order”', ' “ডুপ্লিকেট” হিসেবে বাতিল')], reason:'optional', fn:function(){
    o.lines.forEach(function(l){ m.lines.push(JSON.parse(JSON.stringify(l))); }); m.subtotal += o.subtotal; m.discount += o.discount || 0; m.total = m.subtotal - m.discount + (m.delivery || 0);
    a2Ev(m, L('Merged with ', 'জোড়া দেওয়া হয়েছে: ') + o.id, 'ok'); a2RiskDecide(o, L('Merged into ', 'জোড়া: ') + m.id); A2C.cancel(o, 'DUPLICATE_ORDER', 'Merged into ' + m.id); saveState(); rerender(); toast(L('Merged — one parcel', 'এক পার্সেল হয়েছে')); }}); };
ACT['a2-codoff'] = function(el){ var ph = el.getAttribute('data-ph'), h = a2PhoneHist(ph);
  a2Confirm({title:'Propose COD off for this number', bn:'এই নম্বরে COD বন্ধের প্রস্তাব', sub:esc(a2ph(ph)) + ' · ' + esc(a2HistLine(h)), effects:[L('A proposal goes to the owner’s approvals — nothing changes yet', 'প্রস্তাব মালিকের কাছে যাবে — এখনই কিছু বদলায় না'), L('If approved: this number can order with advance payment only', 'অনুমোদন হলে: এই নম্বরে শুধু অগ্রিম দিয়ে অর্ডার')], reason:true, ok:'Send proposal', okBn:'প্রস্তাব পাঠান',
    fn:function(r){ a2S().appr.push({id:'ap' + Date.now(), kind:'codOff', kindEn:'COD off for a number', kindBn:'নম্বরে COD বন্ধ', phone:ph, why:r, by:a2Who(), at:Date.now(), st:'waiting'}); a2Log('Proposed COD off for ' + ph); saveState(); rerender(); toast(L('Proposal sent to the owner', 'মালিকের কাছে প্রস্তাব গেছে')); }}); };
ACT['a2r-block'] = function(el){ var ph = el.getAttribute('data-ph'); a2Confirm({title:'Propose a block', bn:'ব্লকের প্রস্তাব', effects:[L('Goes to the owner; only the owner can confirm a block (hard rule)', 'শুধু মালিক ব্লক নিশ্চিত করতে পারেন')], reason:true, ok:'Send proposal', okBn:'প্রস্তাব পাঠান', fn:function(r){ a2S().appr.push({id:'ap' + Date.now(), kind:'block', kindEn:'Block a number', kindBn:'নম্বর ব্লক', phone:ph, why:r, by:a2Who(), at:Date.now(), st:'waiting'}); saveState(); rerender(); toast(L('Proposal sent', 'প্রস্তাব গেছে')); }}); };

