ACT['a2o-confirm'] = function(el){ var id = el.getAttribute('data-id'); if(a2Cmd('confirm', id)){ toast(L('Confirmed ', 'কনফার্ম ') + id); if(el.getAttribute('data-next')) ui('a2conf', {}).id = null; } rerender(); };
