ACT['a2o-cancel'] = function(el){ var o = a2Order(el.getAttribute('data-id'));
  a2Confirm({title:'Cancel ' + o.id + '?', bn:o.id + ' বাতিল করবেন?', body:'<label class="a2-lbl" for="a2cc">' + Le('Reason', 'কারণ') + '</label><select id="a2cc" class="a2-sel" data-f="code">' + Object.keys(A2_CANCEL).filter(function(k){ return k !== 'CUSTOMER_CHANGE_AFTER_BOOKING'; }).map(function(k){ return '<option value="' + k + '">' + Le(A2_CANCEL[k][0], A2_CANCEL[k][1]) + '</option>'; }).join('') + '</select><div style="height:10px"></div>',
    effects:[L('Held stock goes back to sale', 'ধরা স্টক বিক্রিতে ফেরে'), a2Paid(o) ? L('A refund request for ', 'রিফান্ডের অনুরোধ হবে: ') + a2tk(a2Paid(o)) + L(' is created (never paid by itself)', '') : L('Nothing was paid — no refund', 'টাকা দেওয়া হয়নি — রিফান্ড নেই'), L('One cancel notice is sent (outside the message cap)', 'একটা নোটিস যাবে')], reason:'optional', tone:'badf', ok:'Cancel order', okBn:'বাতিল করুন',
    fn:function(r, v){ if(v.code === 'OTHER' && !r) return toast(L('“Other” needs a note', '“অন্য” হলে নোট লিখুন')); if(A2C.cancel(o, v.code, r)){ saveState(); toast(L('Cancelled', 'বাতিল হয়েছে')); } rerender(); }}); };
