ACT['a2o-outcome'] = function(el){ UI.a2pop = null; var o = a2Order(el.getAttribute('data-id'));
  a2Confirm({title:'Record outcome', bn:'ফল লিখুন', body:'<select class="a2-sel" data-f="k"><option value="partial">' + Le('Partly delivered — customer kept some items', 'আংশিক — কিছু রেখেছে') + '</option><option value="failed">' + Le('Failed attempt — will try again', 'ব্যর্থ চেষ্টা — আবার যাবে') + '</option><option value="charge">' + Le('Return with delivery charge paid', 'চার্জ দিয়ে ফেরত') + '</option></select>', effects:[L('Money and stock effects follow the outcome (kept items count as sales; returns come back through QC)', 'বিক্রি আর স্টক ফল অনুযায়ী হবে')], reason:'optional',
    fn:function(r, v){ var a = a2O(o); if(v.k === 'partial'){ a.ost = 'PARTIALLY_DELIVERED'; a.ship = 'PARTIALLY_DELIVERED'; a.keptShare = .5; o.deliveredAt = Date.now(); a.outAt = Date.now(); a.ret = {id:'RT-' + o.id.replace(/\D/g, ''), type:'refused', stage:'approved', status:'EXPECTED', at:Date.now(), items:[{line:o.lines.length - 1}], ev:[]}; }
      else if(v.k === 'failed'){ a.ship = 'ATTEMPT_FAILED'; a.exNote = r || 'Failed attempt'; } else { A2C.event(o, 'refused'); a.chargePaid = true; }
      a2Sync(o); a2Ev(o, L('Outcome recorded: ', 'ফল লেখা হয়েছে: ') + v.k, 'warn'); saveState(); rerender(); }}); };

